'use strict';
window.clearProfileMedal=()=>{document.getElementById('avatar-badge').value='none';previewPlayerProfile();};
window.renderProfileMedals=()=>{
 const box=document.getElementById('profile-medal-picker');if(!box||!profileDraft)return;box.replaceChildren();const S=KanjiAvatarStyle,progress=gameState.iconProgress||{},selected=document.getElementById('avatar-badge').value||profileDraft.appearance.badge;
 const groups=new Map();for(const reward of S.badges.filter(b=>b.key&&KanjiAbilityGuide.matches(document.getElementById('profile-medal-filter')?.value,S.badgeUnlocked(b.id,progress),b,progress,gameState,KANJI_DATABASE))){const group=reward.kind||'basic';if(!groups.has(group))groups.set(group,[]);groups.get(group).push(reward);}
 for(const [kind,rewards]of groups){const section=document.createElement('section');section.className='profile-honor-group';const title=document.createElement('h4');title.textContent=kind==='basic'?'基本の勲章':rewards[0].name.replace(/・[銅銀金]$/,'');const grid=document.createElement('div');grid.className='profile-honor-grid';section.append(title,grid);box.append(section);
  for(const reward of rewards){const unlocked=S.badgeUnlocked(reward.id,progress),button=document.createElement('button');button.type='button';button.className='profile-honor-choice profile-medal-choice';button.dataset.medalId=reward.id;button.disabled=!unlocked;button.setAttribute('aria-pressed',String(selected===reward.id));button.setAttribute('aria-label',reward.name+'：'+reward.condition+'（'+(unlocked?'解放済み':'未解放')+'）');const art=document.createElement('span');art.className='player-name-badge medal-preview';art.dataset.glow=profileDraft.glow||'none';art.dataset.medalTier=reward.tier===undefined?'legacy':String(reward.tier);art.innerHTML=S.badgeSvg(reward.id);art.style.color=S.colors[profileDraft.color]?.[1]||'#dac18a';const name=document.createElement('strong');name.textContent=reward.name;const condition=document.createElement('span');condition.textContent=reward.condition;const status=document.createElement('small');status.textContent=(unlocked?'解放済み・選択できます':'未解放')+' ／ 進捗 '+Math.min(progress[reward.key]||0,reward.value)+' / '+reward.value;button.append(art,name,condition,status);button.onclick=()=>{if(!S.badgeUnlocked(reward.id,gameState.iconProgress))return;document.getElementById('avatar-badge').value=reward.id;previewPlayerProfile();};grid.append(button);}
 }
 if(!box.children.length)box.textContent='この条件に合う勲章はありません。';
};
